-- Conventions for every table:
--   id          UUID (v7, text) generated by the application; the primary key.
--   created_on  timestamptz, set on insert.
--   created_by  who created the row; NULL until accounts exist.
--   updated_on  timestamptz, NULL until the row is first updated, then set by a trigger
--               (set_updated_on) unless the update sets it explicitly.
--   updated_by  who last updated the row; NULL until accounts exist.
-- A NULL cost_usd means "not known yet / provider did not report".

CREATE FUNCTION set_updated_on() RETURNS trigger AS $$
BEGIN
    NEW.updated_on := now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE sessions (
    id         TEXT PRIMARY KEY,
    kind       TEXT NOT NULL CHECK (kind IN ('blog', 'chat')),
    url        TEXT,
    created_on TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT,
    updated_on TIMESTAMPTZ,
    updated_by TEXT
);
CREATE TRIGGER sessions_set_updated_on BEFORE UPDATE ON sessions
FOR EACH ROW WHEN (NEW.updated_on IS NOT DISTINCT FROM OLD.updated_on)
EXECUTE FUNCTION set_updated_on();

CREATE TABLE messages (
    id         TEXT PRIMARY KEY,
    session_id TEXT NOT NULL REFERENCES sessions(id),
    role       TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
    text       TEXT,
    audio_key  TEXT,
    created_on TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT,
    updated_on TIMESTAMPTZ,
    updated_by TEXT
);
CREATE INDEX messages_session ON messages(session_id);
CREATE TRIGGER messages_set_updated_on BEFORE UPDATE ON messages
FOR EACH ROW WHEN (NEW.updated_on IS NOT DISTINCT FROM OLD.updated_on)
EXECUTE FUNCTION set_updated_on();

-- Maps an adapter's own handle for a conversation (e.g. Telegram chat_id:message_id)
-- to a session, so threading works without Core knowing the platform.
CREATE TABLE thread_map (
    id         TEXT PRIMARY KEY,
    adapter    TEXT NOT NULL,
    thread_ref TEXT NOT NULL,
    session_id TEXT NOT NULL REFERENCES sessions(id),
    created_on TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT,
    updated_on TIMESTAMPTZ,
    updated_by TEXT
);
CREATE INDEX thread_map_ref ON thread_map(adapter, thread_ref);
CREATE TRIGGER thread_map_set_updated_on BEFORE UPDATE ON thread_map
FOR EACH ROW WHEN (NEW.updated_on IS NOT DISTINCT FROM OLD.updated_on)
EXECUTE FUNCTION set_updated_on();

-- One row per provider call. Inserted when the call succeeds; usage and cost
-- are filled in once the provider reports them (NULL until then).
CREATE TABLE ledger (
    id         TEXT PRIMARY KEY,
    session_id    TEXT NOT NULL REFERENCES sessions(id),
    role          TEXT NOT NULL CHECK (role IN ('llm', 'stt', 'tts')),
    provider      TEXT NOT NULL,
    model         TEXT NOT NULL,
    generation_id TEXT,
    chars         BIGINT NOT NULL DEFAULT 0,
    input_units   BIGINT,
    output_units  BIGINT,
    cost_usd      DOUBLE PRECISION,
    created_on TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT,
    updated_on TIMESTAMPTZ,
    updated_by TEXT
);
CREATE INDEX ledger_session ON ledger(session_id);
CREATE TRIGGER ledger_set_updated_on BEFORE UPDATE ON ledger
FOR EACH ROW WHEN (NEW.updated_on IS NOT DISTINCT FROM OLD.updated_on)
EXECUTE FUNCTION set_updated_on();

-- Cleaned article text, fetched once per URL.
CREATE TABLE page_cache (
    id         TEXT PRIMARY KEY,
    url_hash TEXT NOT NULL,
    url      TEXT NOT NULL,
    text     TEXT NOT NULL,
    created_on TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT,
    updated_on TIMESTAMPTZ,
    updated_by TEXT
);
CREATE INDEX page_cache_url_hash ON page_cache(url_hash);
CREATE TRIGGER page_cache_set_updated_on BEFORE UPDATE ON page_cache
FOR EACH ROW WHEN (NEW.updated_on IS NOT DISTINCT FROM OLD.updated_on)
EXECUTE FUNCTION set_updated_on();

-- Finished audio per URL and voice settings, so re-sharing a link costs nothing.
CREATE TABLE audio_cache (
    id         TEXT PRIMARY KEY,
    url_hash  TEXT    NOT NULL,
    tts_model TEXT    NOT NULL,
    voice     TEXT    NOT NULL,
    audio_key TEXT    NOT NULL,
    seconds   BIGINT NOT NULL,
    created_on TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT,
    updated_on TIMESTAMPTZ,
    updated_by TEXT
);
CREATE INDEX audio_cache_key ON audio_cache(url_hash, tts_model, voice);
CREATE TRIGGER audio_cache_set_updated_on BEFORE UPDATE ON audio_cache
FOR EACH ROW WHEN (NEW.updated_on IS NOT DISTINCT FROM OLD.updated_on)
EXECUTE FUNCTION set_updated_on();
